diagrams.business_process_flow:
@startuml
start
:Customer membuka halaman menu;
:Customer menambahkan menu ke keranjang;
:Customer melakukan preorder dan mengisi data;
:Sistem membuat kode pesanan unik;
:Sistem menyimpan order dan order items;
:Customer diarahkan ke halaman pembayaran;
:Admin melihat pesanan baru di daftar pesanan;
:Admin memproses pesanan;
if (Pesanan siap?) then (Ya)
  :Admin menandai pesanan sebagai siap;
  :Admin menandai pesanan sebagai selesai;
else (Tidak)
  :Admin membatalkan pesanan;
endif
:Customer melacak status pesanan dengan kode;
:Customer memberi rating setelah pesanan selesai;
stop
@enduml

activity_diagrams.diagram_script:
@startuml
start
:Admin membuka halaman login;
:Admin mengisi username dan password;
:Sistem memverifikasi kredensial;
if (Kredensial valid?) then (Ya)
  :Sistem membuat session login;
  :Sistem mengarahkan ke dashboard;
else (Tidak)
  :Sistem menampilkan pesan error;
endif
stop
@enduml

@startuml
start
:Admin membuka halaman manajemen menu;
if (Aksi?) then (Tambah/Edit Menu)
  :Admin mengisi data menu;
  :Admin mengunggah gambar menu;
  :Sistem mengunggah gambar ke Cloudinary;
  :Sistem menyimpan data menu ke database;
else (Toggle Status)
  :Admin memilih menu untuk diaktifkan/nonaktifkan;
  :Sistem memperbarui status menu;
endif
:Sistem menampilkan daftar menu terbaru;
stop
@enduml

@startuml
start
:Admin membuka halaman daftar pesanan;
:Admin memilih pesanan;
if (Status baru?) then (Diproses)
  :Sistem mengubah status menjadi diproses;
else (Lainnya)
  if (Status baru?) then (Siap)
    :Sistem mengubah status menjadi siap;
  else (Lainnya)
    if (Status baru?) then (Selesai)
      :Sistem mengubah status menjadi selesai;
    else (Batal)
      :Sistem mengubah status menjadi dibatalkan;
    endif
  endif
endif
:Admin dapat mencetak struk pesanan;
stop
@enduml

@startuml
start
:Admin membuka halaman input pesanan walk-in;
:Admin memilih menu dan jumlah item;
:Admin mengisi data pelanggan;
:Sistem membuat order dengan sumber WALKIN;
:Sistem menyimpan order beserta item pesanan;
:Sistem menampilkan konfirmasi pesanan;
stop
@enduml

@startuml
start
:Customer memilih menu;
:Customer menambahkan menu ke keranjang;
:Sistem menyimpan item keranjang berdasarkan session_id;
:Customer membuka halaman keranjang;
:Customer melanjutkan ke preorder;
:Customer mengisi data pemesanan;
:Sistem membuat kode pesanan unik;
:Sistem menyimpan order dan order items;
:Sistem mengosongkan keranjang;
:Customer diarahkan ke halaman pembayaran;
stop
@enduml

@startuml
start
:Customer membuka halaman lacak pesanan;
:Customer memasukkan kode pesanan;
:Sistem mencari order berdasarkan kode;
if (Order ditemukan?) then (Ya)
  :Sistem menampilkan status pesanan;
  if (Status selesai?) then (Ya)
    :Customer memberikan rating;
    :Sistem menyimpan rating dan memperbarui rata-rata rating menu;
  else (Tidak)
    :Customer menunggu pesanan diproses;
  endif
else (Tidak)
  :Sistem menampilkan pesan pesanan tidak ditemukan;
endif
stop
@enduml

@startuml
start
:Customer mengirim pesan ke chatbot;
:Sistem meneruskan pesan ke layanan AI;
:Sistem mendeteksi maksud pesan;
if (Ada aksi terdeteksi?) then (Ya)
  :Sistem menjalankan aksi terkait, misal cari menu atau tambah ke keranjang;
else (Tidak)
  :Sistem menyusun balasan langsung;
endif
if (Keranjang tidak kosong dan ada sinyal checkout?) then (Ya)
  :Sistem menampilkan panel checkout;
else (Tidak)
endif
:Sistem mengirim balasan ke customer;
stop
@enduml
